const config={name:'Trapiche',phone:'+5588994554399',whatsappConfirmed:true,address:'Av. Pref. Jaques Nunes, 1923 — Centro, Tianguá — CE, 62320-000',photos:{pizza:'assets/pizza.png',carne:'assets/carne.png',carneiro:'assets/carneiro.png'},services:['Refeição no local','Retirada na porta','Entrega']};
const route='https://www.google.com/maps/place/Trapiche/@-3.7184298,-40.9932167,17.5z/data=!4m6!3m5!1s0x7eb49d6d286d88b:0xe65a7c63d0049b71!8m2!3d-3.7183867!4d-40.9897716!16s%2Fg%2F11nnhywjbg?entry=ttu&g_ep=EgoyMDI2MTAwNy4wIKXMDSoASAFQAw%3D%3D';
document.querySelectorAll('[data-route]').forEach(a=>{a.href=route;a.target='_blank';a.rel='noopener noreferrer'});
document.querySelectorAll('[data-phone]').forEach(a=>a.href='tel:'+config.phone);
document.querySelectorAll('[data-contact]').forEach(a=>{a.href='https://api.whatsapp.com/send/?phone=5588994554399&text='+encodeURIComponent('ola! gostaria de fazer um pedido.')+'&type=phone_number&app_absent=0';a.target='_blank';a.rel='noopener noreferrer';});
document.getElementById('year').textContent=new Date().getFullYear();
const toggle=document.querySelector('.menu-toggle'),nav=document.getElementById('navigation');
function closeMenu(){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir menu');nav.classList.remove('open')}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');nav.classList.toggle('open',open)});
nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();toggle.focus()}});
document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu()});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('#navigation a[href^="#"]').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}})},{rootMargin:'-20% 0px -55% 0px'});document.querySelectorAll('main section[id]').forEach(s=>observer.observe(s));
const paths={pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',table:'<path d="M3 10h18M5 10v11M19 10v11M7 3v7M17 3v7M3 5h8M13 5h8"/>',bag:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M9 8V5a3 3 0 0 1 6 0v3"/>',delivery:'<path d="M3 5h11v12H3zM14 9h4l3 4v4h-7"/><circle cx="7" cy="18" r="3"/><circle cx="18" cy="18" r="3"/>'};document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[el.dataset.icon]+'</svg>');
const schema=document.createElement('script');schema.type='application/ld+json';schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'Restaurant',name:config.name,telephone:config.phone,servesCuisine:['Pizza','Regional brasileira'],priceRange:'R$ 40–60 por pessoa',address:{'@type':'PostalAddress',streetAddress:'Av. Pref. Jaques Nunes, 1923',addressLocality:'Tianguá',addressRegion:'CE',postalCode:'62320-000',addressCountry:'BR'}});document.head.appendChild(schema);
